#!/usr/bin/env python3
# flake8: noqa

import subprocess
import argparse
import re
import os
import sys

COLOR_Off = '\033[0m'
COLOR_Red = '\033[0;31m'
COLOR_Yellow = '\033[0;33m'
COLOR_Cyan = '\033[0;36m'


class DockerTgr(object):
    CONFIG = [
        '/home/cus/loaded-cus.ini',
        '/home/rtg/loaded-rtg.ini',
        '/opt/cus/etc/cus.ini',
        '/opt/rtg/etc/rtg.ini',
    ]
    LOG = '/tmp/docker_tgr.log'
    WS_SS_PHY_ETH_TAB = []
    WS_MS_PHY_ETH_TAB = []

    TGR_NETWORK = {
        'ip-mask': None,
        'ipv6-mask': None,
        'ss-ip-addr-pool': None,
        'ss-ipv6-addr-pool': None,
        'lte-network-v6gw': None,
        'ws-ss-if': None,
        'ws-ms-if': None,
        'tgr-if': {
            'ms': None,
            'ss': None,
        },
        'tgr-ip': {
            'ms': None,
            'ss': None,
        },
        'etgr-ip': {
            'ms': None,
            'ss': None,
        },
        'tgr-ipv6': {
            'ms': None,
            'ss': None,
        },
        'etgr-ipv6': {
            'ms': None,
            'ss': None,
        },
    }

    # TODO: Add dynamic CPU assignment algorithm based on /proc/cpuinfo
    CPUSET = {
        '1': '8-10',
        '2': '11-13',
        '3': '14-16',
        '4': '17-19',
        '5': '20-22',
        '6': '23-25',
        '7': '26-28',
        '8': '29-31',
    }

    COREUTILS = [
        'arch',
        'b2sum', 'base32', 'base64', 'basename',
        'cat', 'chcon', 'chgrp', 'chmod', 'chown', 'chroot', 'cksum', 'comm', 'cp', 'csplit', 'cut',
        'date', 'dd', 'df', 'dir', 'dircolors', 'dirname', 'du',
        'echo', 'env', 'expand', 'expr',
        'factor', 'false', 'fmt', 'fold',
        'groups',
        'head', 'hostid',
        'id', 'install',
        'join',
        'link', 'ln', 'logname', 'ls',
        'md5sum', 'mkdir', 'mkfifo', 'mknod', 'mktemp', 'mv',
        'nice', 'nl', 'nohup', 'nproc', 'numfmt',
        'od',
        'paste', 'pathchk', 'pinky', 'pr', 'printenv', 'printf', 'ptx', 'pwd',
        'readlink', 'realpath', 'rm', 'rmdir', 'runcon',
        'seq', 'sha1sum', 'sha224sum', 'sha256sum', 'sha384sum', 'sha512sum', 'shred', 'shuf',
        'sleep', 'sort', 'split', 'stat', 'stdbuf', 'stty', 'sum', 'sync',
        'tac', 'tail', 'tee', 'test', 'timeout', 'touch', 'tr', 'true', 'truncate', 'tsort', 'tty',
        'uname', 'unexpand', 'uniq', 'unlink', 'uptime', 'users',
        'vdir',
        'wc', 'who', 'whoami',
        'yes'
    ]

    BIN = [
        'groupadd',
        'useradd',
        'grep',
        'sed',
        '/bin/sh',
        '/lib/x86_64-linux-gnu/libnss_*',
        '/lib/x86_64-linux-gnu/security/pam*',
    ]

    DIR = [
        '/etc/',
    ]

    def __init__(self):
        self.outdir = None
        self.libs = {'virtual': {}, 'static': {}, 'shared': {}, 'loader': {}}
        self.dirs = {}
        self.binaries = []
        self.errors = 0
        self.warns = 0
        self.config_lines = []
        self.config = {}
        self.config_path = None
        self.stop = False
        self.ipv6 = False
        self.type = None  # 'cus' or 'rtg'
        self.multi_vtgrs_mode = False
        self._open_log()

    def parse_args(self):
        default_config = self._get_default_config()
        config_required = False if default_config else True

        parser = argparse.ArgumentParser(description='Docker TGR image generator and runner', formatter_class=argparse.ArgumentDefaultsHelpFormatter)
        parser.add_argument('-o', '--outdir', dest='outdir', default='/root/tgrimg', help='Output directory for image filesystem')
        parser.add_argument('-c', '--config', dest='config', required=config_required, default=default_config, help='Path to cus.ini/rtg.ini file')
        parser.add_argument('-s', '--stop', dest='stop', action='store_true', help='Stop and remove vTGR containers')
        parser.add_argument('-6', '--ipv6', dest='ipv6', action='store_true', help='Configure IPv6 in addition to IPv4')
        parser.add_argument('--ip-mask', dest='ip_mask', default='24', help='IPv4 mask of the physical interface towards TGR IP network')
        parser.add_argument('--ipv6-mask', dest='ipv6_mask', default='64', help='IPv6 mask')
        parser.add_argument('--ss-ip-addr-pool', dest='ss_ip_addr_pool', default='185.4.0.0/16', help='SS side IP address pool')
        parser.add_argument('--ss-ipv6-addr-pool', dest='ss_ipv6_addr_pool', default='fd00:185:4::/64', help='SS side IPv6 address pool')
        parser.add_argument('--lte-network-v6gw', dest='lte_network_v6gw', default='fd00::10:0:2:1', help='IPv6 LTE traffic network gateway')
        parser.add_argument('--ws-ms-if', dest='ws_ms_if', default='eth102', help='Virtual interface associated with WS physical interface for TGR MS')
        parser.add_argument('--ws-ss-if', dest='ws_ss_if', default='eth102', help='Virtual interface associated with WS physical interface for TGR SS')
        parser.add_argument('--ms-log-if', dest='ms_log_if', default='eth100', help='Virtual interface for TGR MS inside MS container (=ue_interface)')
        parser.add_argument('--ss-log-if', dest='ss_log_if', default='eth101', help='Virtual interface for TGR SS inside SS container (=ss_interface)')
        parser.add_argument('--ms-ip', dest='ms_ip', default='10.0.2.100', help='IP of the virtual interface for TGR MS (=ip_addr of MS)')
        parser.add_argument('--ss-ip', dest='ss_ip', default='10.0.2.101', help='IP of the virtual interface for TGR SS (=ip_addr of SS)')
        parser.add_argument('--ms-etgr-ip', dest='ms_etgr_ip', default='10.0.2.102', help='IP of the virtual interface for eTGR MS (=etgr_ip_addr of MS)')
        parser.add_argument('--ms-ipv6', dest='ms_ipv6', default='fd00::10:0:2:100', help='IPv6 of the virtual interface for TGR MS (=ipv6_addr of MS)')
        parser.add_argument('--ss-ipv6', dest='ss_ipv6', default='fd00::10:0:2:101', help='IPv6 of the virtual interface for TGR SS (=ipv6_addr of SS)')
        parser.add_argument('--ms-etgr-ipv6', dest='ms_etgr_ipv6', default='fd00::10:0:2:102', help='IPv6 of the virtual interface for eTGR MS (=etgr_ipv6_addr of MS)')

        args = parser.parse_args()

        self.outdir = args.outdir
        self.config_path = args.config
        self.stop = args.stop
        self.ipv6 = args.ipv6
        self.TGR_NETWORK['ip-mask'] = args.ip_mask
        self.TGR_NETWORK['ipv6-mask'] = args.ipv6_mask
        self.TGR_NETWORK['ss-ip-addr-pool'] = args.ss_ip_addr_pool
        self.TGR_NETWORK['ss-ipv6-addr-pool'] = args.ss_ipv6_addr_pool

        self.TGR_NETWORK['lte-network-v6gw'] = args.lte_network_v6gw
        self.TGR_NETWORK['ws-ms-if'] = args.ws_ms_if
        self.TGR_NETWORK['ws-ss-if'] = args.ws_ss_if
        self.TGR_NETWORK['tgr-if']['ms'] = args.ms_log_if
        self.TGR_NETWORK['tgr-if']['ss'] = args.ss_log_if
        self.TGR_NETWORK['tgr-ip']['ms'] = args.ms_ip
        self.TGR_NETWORK['tgr-ip']['ss'] = args.ss_ip
        self.TGR_NETWORK['etgr-ip']['ms'] = args.ms_etgr_ip
        self.TGR_NETWORK['tgr-ipv6']['ms'] = args.ms_ipv6
        self.TGR_NETWORK['tgr-ipv6']['ss'] = args.ss_ipv6
        self.TGR_NETWORK['etgr-ipv6']['ms'] = args.ms_etgr_ipv6

        if re.search(r'cus', self.config_path):
            self.type = 'cus'
        elif re.search(r'rtg', self.config_path):
            self.type = 'rtg'
        else:
            self._warn('Cannot determine simulator type, assuming CUS')
            self.type = 'cus'

    def run(self):
        if not self._check_root():
            return

        if self.stop:
            return self._stop_containers()

        if not self._make_outdir():
            return

        if not self._read_config():
            return

        if not self._autodetect_ws_eth():
            return

        if self._tgrs_alive():
            return

        self._debug(f'*** CONFIG={self.config}')
        self._debug(f'*** TGR_NETWORK={self.TGR_NETWORK}')

        self._add_binaries()
        self._get_shared_libs()
        self._copy_bins()
        self._copy_dirs()
        self._build_docker_image()

        self._run_all_containers()
        self._add_ws_bridges()
        if not self._add_all_veths():
            return
        self._add_all_ws_routes()
        self._update_config()

        self._add_systemd_service()

        if self.warns:
            print(f'Execution warnings: {self.warns}')
        if self.errors:
            print(f'Execution errors: {self.errors}')
        else:
            self._info("All TGRs should be up and running now - please execute 'config update' and 'config remote update' on executor console (telnet 0 1234)")

    def _get_default_config(self):
        for cf in self.CONFIG:
            if os.path.isfile(cf):
                return cf
        return None

    def _add_binaries(self):
        for binary in self.COREUTILS:
            self._add_binary(binary)
        for binary in self.BIN:
            self._add_binary(binary)

    def _add_binary(self, binary):
        if not re.search(r'^/', binary):
            out, rc = self._execute(f'which {binary}', silent=True, report_exec=False)
            for line in out:
                ln = line.strip()
                if re.search(r'^/', ln):
                    binary = ln
        if re.search(r'^/', binary):
            self.binaries.append(binary)
        else:
            self._error(f'Cannot get full path of binary: {binary}')

    def _get_shared_libs(self):
        for binfile in self.binaries:
            self._get_libs(binfile)

    def _already_checked(self, binary):
        if binary in self.libs['static'] or binary in self.libs['shared']:
            return 1
        return 0

    def _get_libs(self, binary):
        if self._already_checked(binary):
            return
        out, rc = self._execute(f'ldd {binary}', report_exec=False)
        for line in out:
            ln = line.strip()
            if ln == '':
                continue

            m = re.search(r'^(/\S+)\s+\(([a-f0-9x]+)\)$', ln)
            if m:
                path = m.group(1)
                addr = m.group(2)
                self.libs['loader'][path] = addr
                self._get_libs(path)
                continue

            m = re.search(r'^([^/\s]+)\s+\(([a-f0-9x]+)\)$', ln)
            if m:
                vlib = m.group(1)
                addr = m.group(2)
                self.libs['virtual'][vlib] = addr
                continue

            m = re.search(r'^(\S+)\s+=>\s+(/\S+)\s+\([a-f0-9x]+\)$', ln)
            if m:
                lib = m.group(1)
                path = m.group(2)
                self.libs['shared'][path] = lib
                self._get_libs(path)
                continue

            if re.search(r'^statically linked$', ln) or re.search(r'^not a dynamic executable$', ln):
                self.libs['static'][binary] = 1 if binary not in self.libs['static'] else self.libs['static'][binary] + 1
                continue

            if re.search(r'^/.*:$', ln):
                continue

            self._error(f'[{binary}] Unknown lib format: [{ln}]')

    def _copy_bins(self):
        self._debug(f'Copying files to {self.outdir}')
        files = sorted(self.libs['loader'].keys())
        self._copy_files(files)
        files = sorted(self.libs['static'].keys())
        self._copy_files(files)
        files = sorted(self.libs['shared'].keys())
        self._copy_files(files)
        self._copy_files(self.binaries)

    def _copy_files(self, files):
        for v in files:
            path = os.path.dirname(v)
            m = re.search(r'^/(.*)$', path)
            if m:
                path = m.group(1)
            outd = f'{self.outdir}/{path}/'
            if not os.path.isdir(outd):
                self._execute(f'mkdir -p {outd}')
            self._execute(f'cp -L {v} {outd}', report_exec=False)
            parts = path.split('/')
            self.dirs[parts[0]] = 1

    def _copy_dirs(self):
        self._debug('Copying directories to ' + self.outdir)
        for dr in self.DIR:
            directory = dr
            opt = '-rL'
            m = re.search(r'^(.*)/$', dr)
            if m:
                directory = m.group(1)
                opt = '-r'

            m = re.search(r'^/([^/].*)$', directory)
            if m:
                dst = '{}/{}'.format(self.outdir, m.group(1))
                self._execute(f'mkdir -p {dst}')
                self._execute(f'cp {opt} {directory}/* {dst}')
                parts = directory.split('/')
                self.dirs[parts[1]] = 1
            else:
                self._error(f'Wrong DIR entry: {directory}')

    def _run_docker(self):
        out, rc = self._execute('systemctl is-active docker', can_fail=True)
        if rc == 0:
            return
        out, rc = self._execute('systemctl is-enabled docker', can_fail=True)
        if rc != 0:
            self._execute('systemctl enable docker', can_fail=True)
        self._execute('systemctl start docker')

    def _make_docker_initial_script(self, init_script_name):
        script_content = \
"""#!/bin/bash
# This script is executed inside the container

error() {
    echo "Error in line ${BASH_LINENO[0]}"
    exit ${BASH_LINENO[0]}
}

mkdir -p /run/sshd
mkdir -p /var/run
mkdir -p /var/spool
mkdir -p /var/tmp
chmod 777 /var/tmp
mkdir -p /root
mkdir -p /tmp
chmod 777 /tmp
chown ute /home/ute

sed -i 's/enforce_for_root//g' /etc/pam.d/common-password

SSHD_CONFIG_FILE="/etc/ssh/sshd_config"
if grep -q "^PermitRootLogin" "$SSHD_CONFIG_FILE"; then
    sed -i '/^PermitRootLogin/s/.*/PermitRootLogin yes/' "$SSHD_CONFIG_FILE"
else
        echo 'PermitRootLogin yes' >> "$SSHD_CONFIG_FILE"
fi

mkdir -p /dev/net;
mknod /dev/net/tun c 10 200;

echo "ute:ute" | chpasswd || error
echo "root:cussim" | chpasswd || error

service ssh start

"""
        # Specify the file name
        script_name = os.path.abspath(self.outdir) + "/" + init_script_name

        # Open the file in write mode and write the content
        with open(script_name, 'w') as file:
            file.write(script_content)
        pass

    def _make_dockerfile(self, init_script_name):
        dockerfile = os.path.abspath(self.outdir) + '/Dockerfile'
        lines = ['FROM scratch']
        for dr in sorted(self.dirs.keys()):
            lines.append(f'ADD {dr} /{dr}/')

        lines.append('ADD home /home/')

        lines.append('ENV PATH=/usr/sbin:/usr/bin:/sbin:/bin')
        lines.append('USER root:root')

        lines.append(f'COPY {init_script_name} /tmp/{init_script_name}')
        lines.append(f'RUN chmod +x /tmp/{init_script_name}')
        lines.append(f'CMD /tmp/{init_script_name} && /bin/bash')

        with open(dockerfile, 'w') as dfile:
            for ln in lines:
                dfile.writelines([ln, '\n'])

    def _build_docker_image(self):
        self._run_docker()
        init_script_name = "docker_tgr_init.sh"
        self._make_docker_initial_script(init_script_name)
        self._make_dockerfile(init_script_name)
        self._execute(f'mkdir -p {self.outdir}/home/ute')
        self._execute(f'chown ute:root {self.outdir}/home/ute')
        out, rc = self._execute(f'docker build --tag tgr {self.outdir}')
        if rc != 0:
            self._die(f"Cannot build docker image \nCODE: {rc}\nRET: {out}")

    def _add_dir(self, ndir):
        self._execute('mkdir -p ' + ndir)
        self._execute('chown ute:root ' + ndir)
        self._execute('chmod -R 777 ' + ndir)

    def _container_name(self, side):
        return f'{side}_tgr'

    def _run_all_containers(self):
        for tgr_number in sorted(self.config.keys()):
            side_number = self._get_tgr_side(tgr_number)
            self._info(f'Running container: {side_number}')
            self._run_container(side=side_number)

    def _run_container(self, side):
        tgr_dir = f'/home/cus/tgr_{side}'
        container_name = self._container_name(side)
        hostname = f'tgr{side.upper()}'
        local_sim_path = '/opt/' + self.type
        self._execute('docker container stop ' + container_name, silent=True)
        self._add_dir(tgr_dir)

        # cpuset = ''
        # srch = re.search(r'(\d+)', side)
        # if srch:
        #     tgr_num = srch.group(1)
        #     if tgr_num in self.CPUSET:
        #         cpuset = self.CPUSET[tgr_num]
        # self._execute('docker network create --ipv6 --subnet fd00:63:75:73::/64 cusip6net')
        out, rc = self._execute('docker run -d -it ' +
                      f'--name {container_name} ' +
                      '--rm ' +
                      # '--privileged ' +
                      '--cap-add NET_ADMIN ' +
                      '--cap-add SYS_ADMIN ' +
                      '--cap-add SYS_NICE ' +
                      '--ulimit memlock=1024000:1024000 ' +
                      # '--cpuset-cpus='{}' '.format(cpuset) +
                      '--mount type=bind,source=/bin,target=/bin,readonly ' +
                      '--mount type=bind,source=/usr,target=/usr,readonly ' +
                      '--mount type=bind,source=/lib,target=/lib,readonly ' +
                      '--mount type=bind,source=/lib64,target=/lib64,readonly ' +
                      # The whole /var cannot be bind due to /var/run pids
                      '--mount type=bind,source=/var/lib,target=/var/lib,readonly ' +
                      '--mount type=bind,source=/var/log,target=/var/log ' +
                      f'--mount type=bind,source={tgr_dir},target={local_sim_path} ' +
                      f'--hostname {hostname} ' +
                      f'--add-host {hostname}:127.0.0.1 ' +
                      '--network none ' +
                      # '--network cusip6net ' +
                      # '--ip6 {} '.format(self.TGR_NETWORK['tgr-ip'][side]) +
                      'tgr')
        if rc != 0:
            self._die(f"Cannot run docker container {container_name} \nCODE: {rc}\nRET: {out}")

    def _get_tgr_side(self, tgr_number):
        side = self._get_from_config(tgr_number=tgr_number, key='side', lo=True)
        if self.multi_vtgrs_mode:
            side_number = side + tgr_number # ss1/ms2/..
        else:
            side_number = side # ss/ms
        return side_number

    def _update_TGR_NETWORK_dict(self):
        if self.multi_vtgrs_mode:
            # remove ss/ms -> ss1/ms2 will be used
            for k, v in self.TGR_NETWORK.items():
                if isinstance(v, dict):
                    self.TGR_NETWORK[k] = {}

        for tgr_number in sorted(self.config.keys()):
            side_number = self._get_tgr_side(tgr_number)

            ethif = self._get_from_config(tgr_number=tgr_number, key='ss_interface') if 'ss' in side_number \
                else self._get_from_config(tgr_number=tgr_number, key='ue_interface')

            ip = self._get_from_config(tgr_number=tgr_number, key='ip_addr')
            eip = self._get_from_config(tgr_number=tgr_number, key='etgr_ip_addr')
            ipv6 = self._get_from_config(tgr_number=tgr_number, key='ipv6_addr')
            eipv6 = self._get_from_config(tgr_number=tgr_number, key='etgr_ipv6_addr')

            self.TGR_NETWORK['tgr-if'][side_number] = ethif
            self.TGR_NETWORK['tgr-ip'][side_number] = ip
            self.TGR_NETWORK['etgr-ip'][side_number] = eip
            self.TGR_NETWORK['tgr-ipv6'][side_number] = ipv6
            self.TGR_NETWORK['etgr-ipv6'][side_number] = eipv6

    def _add_ws_bridges(self):
        ws_ms_if = self.TGR_NETWORK['ws-ms-if']
        ws_ss_if = self.TGR_NETWORK['ws-ss-if']

        self._add_ws_bridge(ws_ms_if, self.WS_MS_PHY_ETH_TAB)
        if ws_ms_if != ws_ss_if:
            self._add_ws_bridge(ws_ss_if, self.WS_SS_PHY_ETH_TAB)

    def _add_ws_bridge(self, ws_vif, eth_tab):
        self._execute(f'ip link add name {ws_vif} type bridge', silent=True)
        # self._execute('ip link set {} mtu 9000'.format(ws_vif), silent=True)
        self._execute(f'ip link set {ws_vif} up', silent=True)
        for (ws_phy, ws_ip, ws_mask) in eth_tab:
            ws_ip_mask = f'{ws_ip}/{ws_mask}'
            self._info(f'Moving IP address {ws_ip_mask} from {ws_phy} to the bridge {ws_vif}')
            self._execute(f'ip link set {ws_phy} master {ws_vif}', silent=True)
            self._execute(f'ip addr del {ws_ip_mask} dev {ws_phy}', silent=True)
            self._execute(f'ip addr add {ws_ip_mask} dev {ws_vif}', silent=True)
        if self.ipv6:
            ip = self.TGR_NETWORK['lte-network-v6gw']
            mask = self.TGR_NETWORK['ipv6-mask']
            ws_ip_mask = f'{ip}/{mask}'
            self._info(f'Adding IPv6 address {ws_ip_mask} to the bridge {ws_vif}')
            self._execute(f'ip addr add {ws_ip_mask} dev {ws_vif}', silent=True)

    def _add_all_veths(self):
        for tgr_number in sorted(self.config.keys()):
            side_number = self._get_tgr_side(tgr_number)
            if not self._add_veth(side_number):
                return False

        return True

    def _add_veth(self, side):
        tgr_if = self.TGR_NETWORK['tgr-if'][side]
        tgr_if_ext = f"{self.TGR_NETWORK['tgr-if'][side]}ext"
        tgr_ip = '{}/{}'.format(self.TGR_NETWORK['tgr-ip'][side], self.TGR_NETWORK['ip-mask'])
        tgr_ipv6 = '{}/{}'.format(self.TGR_NETWORK['tgr-ipv6'][side], self.TGR_NETWORK['ipv6-mask']) \
            if self.TGR_NETWORK['tgr-ipv6'][side] \
            else None
        etgr_ip = '{}/{}'.format(self.TGR_NETWORK['etgr-ip'][side], self.TGR_NETWORK['ip-mask']) \
            if self.TGR_NETWORK['etgr-ip'][side] \
            else None
        etgr_ipv6 = '{}/{}'.format(self.TGR_NETWORK['etgr-ipv6'][side], self.TGR_NETWORK['ipv6-mask']) \
            if self.TGR_NETWORK['etgr-ipv6'][side] \
            else None
        ws_vif = self.TGR_NETWORK['ws-ms-if'] if 'ms' in side else self.TGR_NETWORK['ws-ss-if']
        route_via = self.WS_MS_PHY_ETH_TAB[0][1] if 'ms' in side else self.WS_SS_PHY_ETH_TAB[0][1]

        self._info(f'Adding veth {side}: {tgr_if}, ip={tgr_ip}, eip={etgr_ip}, ipv6={tgr_ipv6}, eipv6={etgr_ipv6}, '
                   f'ws_if={ws_vif} via={route_via}')

        pid = self._get_container_pid(self._container_name(side))
        if not pid:
            self._error(f"Cannot get {side} container PID - probably container is not running")
            return False

        if etgr_ipv6 or tgr_ipv6:
            self._execute(f'nsenter -t {pid} -n sh -c "echo 0 > /proc/sys/net/ipv6/conf/default/disable_ipv6"')
            self._execute(f'nsenter -t {pid} -n sh -c "echo 0 > /proc/sys/net/ipv6/conf/all/disable_ipv6"')

        self._execute(f'ip link add {tgr_if} type veth peer name {tgr_if_ext}')
        # self._execute('ip link set {} mtu 9000'.format(tgr_if))
        # self._execute('ip link set {} mtu 9000'.format(tgr_if_ext))
        self._execute(f'ip link set {tgr_if_ext} master {ws_vif}')
        self._execute(f'ip link set {tgr_if_ext} up')
        self._execute(f'ip link set netns {pid} dev {tgr_if}')
        self._execute(f'nsenter -t {pid} -n ip link set {tgr_if} up')
        self._execute(f'nsenter -t {pid} -n ip addr add {tgr_ip} dev {tgr_if}')
        if etgr_ip:
            self._execute(f'nsenter -t {pid} -n ip addr add {etgr_ip} dev {tgr_if}')
        if etgr_ipv6:
            self._execute(f'nsenter -t {pid} -n ip addr add {etgr_ipv6} dev {tgr_if}')
        if tgr_ipv6:
            self._execute(f'nsenter -t {pid} -n ip addr add {tgr_ipv6} dev {tgr_if}')
        self._execute(f'nsenter -t {pid} -n ip route add default via {route_via} dev {tgr_if}')

        return True

    def _add_all_ws_routes(self):
        ws_vif = self.TGR_NETWORK['ws-ss-if']
        ss_ip_addr_pool = self.TGR_NETWORK['ss-ip-addr-pool']
        self._execute(f'ip route del {ss_ip_addr_pool}', silent=True)
        self._execute(f'ip route add {ss_ip_addr_pool} dev {ws_vif}')
        if self.ipv6:
            ss_ipv6_addr_pool = self.TGR_NETWORK['ss-ipv6-addr-pool']
            self._execute(f'ip -6 route del {ss_ipv6_addr_pool}', silent=True)
            self._execute(f'ip -6 route add {ss_ipv6_addr_pool} dev {ws_vif}')

    def _get_container_pid(self, name):
        out, rc = self._execute("docker inspect --format '{{.State.Pid}}' " + name)
        for line in out:
            ln = line.strip()
            srch = re.search(r'(\d+)', ln)
            if srch:
                return srch.group(1)
        return self._error(f'No container with name: {name}')

    def _check_root(self):
        out, rc = self._execute('id', silent=True, report_exec=False)
        for ln in out:
            srch = re.search(r'uid=(\d+)', ln)
            if srch:
                v = int(srch.group(1))
                if v == 0:
                    return True
        return self._error('You must be root')

    def _make_outdir(self):
        self._execute('mkdir -p ' + self.outdir)
        if os.path.isdir(self.outdir):
            return True
        return self._error('Cannot create OUTDIR: ' + self.outdir)

    def _ip2net(self, ip, mask):
        mask = int(mask)
        ip_dec = self._ip2dec(ip)
        mask_bin_str = '0b' + ('1' * mask) + ('0' * (32 - mask))
        mask_int = int(mask_bin_str, 2)
        return ip_dec & mask_int

    def _ip2dec(self, ip):
        srch = re.search(r'(\d+)\.(\d+)\.(\d+)\.(\d+)', ip)
        return (int(srch.group(1)) * 256 * 256 * 256 +
                int(srch.group(2)) * 256 * 256 +
                int(srch.group(3)) * 256 +
                int(srch.group(4)))

    def _validate_and_get_tgr_ip(self, side):
        tgr_mask = self.TGR_NETWORK['ip-mask']
        tgr_ip = None
        for k, v in self.TGR_NETWORK['tgr-ip'].items():
            if side in k:
                if tgr_ip is not None:
                    tgr_net_curr = self._ip2net(v, tgr_mask)
                    tgr_net_prev = self._ip2net(tgr_ip, tgr_mask)
                    if tgr_net_curr != tgr_net_prev:
                        return self._error(f'TGRs {side.upper()} IPs are not in the same network: {tgr_ip} and {v}')
                tgr_ip = v

        if tgr_ip is None:
            self._error(f'Cannot find TGR {side} IP address')
        return tgr_ip

    def _autodetect_ws_eth(self):
        tgr_ms_ip = self._validate_and_get_tgr_ip('ms')
        tgr_ss_ip = self._validate_and_get_tgr_ip('ss')

        if not tgr_ss_ip or not tgr_ms_ip:
            return self._error('Error during TGR IP auto-detection')

        if not self._autodetect_ws_eth_for_tgr(tgr_ss_ip, "ss", self.WS_SS_PHY_ETH_TAB):
            return False

        if not self._autodetect_ws_eth_for_tgr(tgr_ms_ip, "ms", self.WS_MS_PHY_ETH_TAB):
            return False

        ws_ss_if = self.TGR_NETWORK['ws-ss-if']
        ws_ms_if = self.TGR_NETWORK['ws-ms-if']
        self._debug(f"WS virtual interface for TGR-SS = {ws_ss_if}")
        self._debug(f"WS virtual interface for TGR-MS = {ws_ms_if}")

        if self.WS_SS_PHY_ETH_TAB[0][0] == self.WS_MS_PHY_ETH_TAB[0][0]:
            #same interface - different networks
            if ws_ss_if != ws_ms_if:
                self._error(f'All TGRs belongs to the same network, but are not using the same WS virtual interface')
                return False
        else:
            if ws_ss_if == ws_ms_if:
                # change default - possible PGW/SGW bypass feature here
                new_ws_ss_if = "eth300"
                self._debug(f"WS Virtual interfaces are the same for TGR SS and MS - changing WS virtual interface for SS to {new_ws_ss_if}")
                self.TGR_NETWORK['ws-ss-if'] = new_ws_ss_if

            if self.ipv6:
                self._error("IPv6 is supported only when all TGRs are in the same network")
                return False

        return True

    def _autodetect_ws_eth_for_tgr(self, tgr_ip, side, eth_tab):
        tgr_mask = self.TGR_NETWORK['ip-mask']
        tgr_net = self._ip2net(tgr_ip, tgr_mask)
        self._debug(f'tgr_{side}_ip={tgr_ip}, tgr_mask={tgr_mask}, tgr_{side}_net={tgr_net:08x}')

        eth = None
        ipaddr_out, rc = self._execute('ip addr show', silent=True)
        for ln in ipaddr_out:
            srch = re.search(r'^\d+:\s+([^:]+):', ln)
            if srch:
                eth = srch.group(1)
            else:
                srch = re.search(r'^\s*inet\s+(\d+\.\d+\.\d+\.\d+)/(\d+)\s+', ln)
                if srch:
                    ip = srch.group(1)
                    mask = srch.group(2)
                    net = self._ip2net(ip, mask)
                    self._debug(f'[{eth}] ip={ip}, mask={mask}, net={net:08x}')
                    if eth and tgr_net == net:
                        self._debug(f'Found WS interface: {eth}')
                        eth_tab.append((eth, ip, mask))
        if len(eth_tab) == 0:
            return self._error(f'No network interface on workstation for TGR {side.upper()} network: {tgr_ip}/{tgr_mask}')

        (ws_phy, ws_ip, ws_mask) = eth_tab[0]

        self._info(f'Using WS interface={ws_phy} and IP={ws_ip}/{tgr_mask} for TGR {side.upper()}')
        return True

    def _tgrs_alive(self):
        all_alive = True
        for nbr, ip in self.TGR_NETWORK['tgr-ip'].items():
            out, rc = self._execute(f'ping -c 1 {ip} -W 1')
            if rc == 0:
                self._info(f'TGR {nbr.upper()} is alive')
            else:
                all_alive = False

        self._info('All TGRs are alive' if all_alive else "Not all TGRs are alive")

        return all_alive

    def _read_config(self):
        self._info("Using config {}".format(self.config_path))
        tgr_keys = [
            'ip_addr',
            'ipv6_addr',
            'etgr_ip_addr',
            'etgr_ipv6_addr',
            'user',
            'password',
            'ue_interface',
            'ss_interface',
            'side',
        ]

        try:
            with open(self.config_path, 'r') as cf:
                self.config_lines = cf.readlines()
        except Exception as exc:
            return self._error(f'Cannot open config file: {exc}')

        section = ''
        number = ''
        for i, cfln in enumerate(self.config_lines):
            srch = re.search(r'^\s*\[\s*([^_]+)_(\d+)', cfln)
            if srch:
                section = srch.group(1)
                number = srch.group(2)
                continue

            srch = re.search(r'^\s*\[\s*(\S+)\s*]', cfln)
            if srch:
                section = srch.group(1)
                number = 0
                continue

            if section == 'tgr':
                self._update_config_keys(tgr_keys=tgr_keys, tgr_number=number, cfg_line=cfln, cfg_line_num=i)
                continue

            if section == 'ip_configuration':
                self._parse_ipv6_params(cfln)
                continue

        if len(self.config.keys()) > 2:
            self._info('*** MULTI-vTGRs MODE ON')
            self.multi_vtgrs_mode = True

        if self._detect_ipv6():
            self._info('*** MULTI-vTGRs MODE ON for IPv6')
            self.ipv6 = True
            self.multi_vtgrs_mode = True

        self._update_TGR_NETWORK_dict()

        return True

    def _parse_ipv6_params(self, line):
        ipv6_to_tgr_net = {
            'ss_ipv6_addr_pool': 'ss-ipv6-addr-pool',
            'lte_network_v6gw': 'lte-network-v6gw',
        }
        for key, tgr_net_key in ipv6_to_tgr_net.items():
            val = self._parse_config_line_key(key, line)
            if val is not None:
                self.TGR_NETWORK[tgr_net_key] = val

    def _parse_config_line_key(self, key, line):
        patt = r'^\s*{}\s*=\s*(\S+)'.format(key)
        srch = re.search(patt, line)
        if srch:
            return srch.group(1)
        return None

    def _update_config_keys(self, tgr_keys, tgr_number, cfg_line, cfg_line_num):
        if tgr_number not in self.config:
            self.config[tgr_number] = {}

        for key in tgr_keys:
            val = self._parse_config_line_key(key, cfg_line)
            if val is not None:
                self.config[tgr_number][key] = {'line_num': cfg_line_num, 'value': val}

    def _detect_ipv6(self):
        for tgr_number in self.config.keys():
            if 'ipv6_addr' in self.config[tgr_number] or 'etgr_ipv6_addr' in self.config[tgr_number]:
                return True
        return False

    def _get_from_config(self, tgr_number, key, lo=False):
        if key in self.config[tgr_number]:
            if lo:
                return self.config[tgr_number][key]['value'].lower()
            return self.config[tgr_number][key]['value']
        return None

    def _update_config(self):
        self._set_tgr_config()

        with open(self.config_path, 'w') as cf:
            cf.writelines(self.config_lines)

    def _set_tgr_config(self):
        for tgr_number in sorted(self.config.keys()):
            side_number = self._get_tgr_side(tgr_number)

            if not side_number:
                return self._error(f'Cannot identify side for tgr {tgr_number}')
            if 'ue_interface' in self.config[tgr_number]:
                self._update_in_config(tgr_number, 'ue_interface', self.TGR_NETWORK['tgr-if'][side_number])
            if 'ss_interface' in self.config[tgr_number]:
                self._update_in_config(tgr_number, 'ss_interface', self.TGR_NETWORK['tgr-if'][side_number])

            self._update_in_config(tgr_number, 'ip_addr', self.TGR_NETWORK['tgr-ip'][side_number])
            self._update_in_config(tgr_number, 'etgr_ip_addr', self.TGR_NETWORK['etgr-ip'][side_number])
            self._update_in_config(tgr_number, 'user', 'root')
            self._update_in_config(tgr_number, 'password', 'cussim')
            if self.ipv6:
                self._update_in_config(tgr_number, 'ipv6_addr', self.TGR_NETWORK['tgr-ipv6'][side_number])
                self._update_in_config(tgr_number, 'etgr_ipv6_addr', self.TGR_NETWORK['etgr-ipv6'][side_number])

    def _update_in_config(self, tgr_number, key, new_value):
        if key not in self.config[tgr_number]:
            self._debug(f'Not in config for tgr_{tgr_number}: {key}')
            return
        line_num = self.config[tgr_number][key]['line_num']
        cfg_line = self.config_lines[line_num]
        patt = r'(^\s*{}\s*=\s*)\S+'.format(key)
        srch = re.search(patt, cfg_line)
        self.config_lines[line_num] = srch.group(1) + str(new_value) + '\n'

    def _stop_containers(self):
        out, rc = self._execute('docker ps -a', silent=True)
        tgr_containers = []
        for line in out:
            srch = re.search(r'\s+((ms|ss)\d*_tgr)', line)
            if srch:
                tgr_containers.append(srch.group(1))
        for tgr_cont in tgr_containers:
            self._execute(f'docker container stop {tgr_cont}')

    def _add_systemd_service(self):
        script_repo_path = os.path.abspath(__file__)
        script_dest_path = "/usr/local/bin/docker_tgr.py"
        docker_tgr_service_path = "/lib/systemd/system/docker_tgr.service"
        docker_tgr_service = [
            "[Unit]",
            "Description=Docker vTGRs",
            "After=network-online.target",
            "",
            "[Service]",
            "Type=oneshot",
            "RemainAfterExit=yes",
            "ExecStart={}".format(script_dest_path),
            "ExecStop={} --stop".format(script_dest_path),
            "",
            "[Install]",
            "WantedBy=multi-user.target",
        ]

        self._execute(f'cp {script_repo_path} {script_dest_path}', silent=True)
        self._execute(f'chmod 755 {script_dest_path}')

        out, rc = self._execute('systemctl is-enabled docker_tgr', can_fail=True)
        if rc == 0:
            return

        with open(docker_tgr_service_path, 'w') as dts:
            dts.writelines([f'{ln}\n' for ln in docker_tgr_service])

        self._execute('systemctl daemon-reload')
        self._execute('systemctl enable docker_tgr', can_fail=True)

